{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free Q-values to determine the net stage 1 value.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 logits for repeating the previous trial's stage 1 action.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "stickiness_bonus = np.zeros(2)\n        if last_action != -1:\n            stickiness_bonus[last_action] = stickiness\n            \n        logits_1 = beta_1 * q_stage1_net + stickiness_bonus",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free Q-value using the stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of all unchosen actions towards 0.5 at the end of each trial.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] += decay * (0.5 - q_stage1_mf[unchosen_1])\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] += decay * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    }
  ]
}
